/* Proof-link tracking contract (frozen interface, spec §4).
   The Cloudflare Worker in tracking/** owns the server side; this file only
   mirrors what the page needs to know. Keep both sides in sync. */

/** Beacon endpoint on the same origin (Worker route jarvisweb.lt/t/*). */
export const BEACON_ENDPOINT = '/t/e';

/** Event types the Worker accepts in POST /t/e {code, type}. */
export const EVENT_TYPES = ['view', 'scroll_proof', 'cta_sms', 'cta_call', 'pdf', 'arbcut', 'preview_cta'];

/** 5 chars, no 0/o/1/l/i. Generated by the CRM, one per lead. */
export const CODE_PATTERN = /^[23456789abcdefghjkmnpqrstuvwxyz]{5}$/;

/** First character of a code = niche. Mirrors the Worker `prefixes` config. */
export const TRACKING_PREFIXES = { a: '/rezultatai', p: '/rezultatai' };

/** Preview-funnel form (funnel spec §4): multipart POST on the same origin. */
export const FORM_ENDPOINT = '/t/form';

/** Form limits (funnel spec §4). The Worker enforces the same numbers. */
export const FORM_LIMITS = {
  maxFiles: 8,
  maxFileBytes: 10 * 1024 * 1024,
  maxTotalBytes: 25 * 1024 * 1024,
  maxImageSide: 2000,
  types: [
    'image/jpeg', 'image/png', 'image/webp', 'image/heic', 'image/heif', 'image/gif',
    'application/pdf', 'text/plain',
    'application/msword',
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    'application/vnd.ms-excel',
    'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  ],
  // Some phones report HEIC or Office files with an empty type; accept by extension.
  extensions: ['jpg', 'jpeg', 'png', 'webp', 'heic', 'heif', 'gif', 'pdf', 'txt', 'doc', 'docx', 'xls', 'xlsx'],
};

/** sessionStorage key; the code lives only for the browser tab session. */
export const STORAGE_KEY = 'jw_proof_code';
